arguments.command:
cd /workspace && python3 - <<'EOF'
import json,sys
sys.path.insert(0,'dev')
import ref
ex=json.load(open('examples.json'))
for e in ex:
    got=ref.solve(e['input'])
    want=e['output']
    print(e['name'], 'MATCH' if got==want else 'DIFF')
    if got!=want:
        for g,w in zip(got['cases'],want['cases']):
            for k in g:
                if g[k]!=w[k]: print('  ',k, g[k], w[k])
EOF
